insert into public.region_pages(region_id,title,description,intro,faq,published,indexable,updated_at) values
('1111000000','종로구 누수탐지 지역 안내','서울 종로구 누수 상담과 지역 안내입니다. 실제 시공사례는 작업 지역이 확인된 경우에만 연결합니다.','종로구에서 누수 증상이 보이면 주소, 건물 유형, 물이 보이는 위치와 발견 시점을 전화 상담에서 알려 주세요.','[{"question":"종로구 누수 상담 전 무엇을 알려야 하나요?","answer":"작업 주소, 건물 유형, 물이 보이는 위치와 처음 발견한 시점을 알려 주세요. 원인과 작업 범위는 현장 확인 전까지 단정하지 않습니다."},{"question":"사진만으로 누수 원인과 비용을 확정할 수 있나요?","answer":"사진과 증상은 상담을 위한 참고 정보입니다. 실제 원인, 탐지 방법, 보수 범위와 비용은 현장 상태를 확인한 뒤 안내합니다."}]'::jsonb,true,false,'2026-09-07T00:00:00Z'),
